"""Import a tested Savant-Card build or verify the committed frontend bundle."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parents[1]
INTEGRATION = ROOT / 'custom_components/savant_energy'
ASSETS = INTEGRATION / 'www'
REPOSITORY = 'https://github.com/bballdavis/Savant-Card'


def digest(data):
    return hashlib.sha256(data).hexdigest()


def import_bundle(source):
    revision = subprocess.check_output(['git', '-C', str(source), 'rev-parse', 'HEAD'], text=True).strip()
    origin = subprocess.check_output(['git', '-C', str(source), 'remote', 'get-url', 'origin'], text=True).strip()
    if origin.removesuffix('.git') != REPOSITORY or not re.fullmatch(r'[a-f0-9]{40}', revision):
        raise ValueError('Expected a full commit from bballdavis/Savant-Card')
    changed = subprocess.check_output(['git', '-C', str(source), 'diff', '--name-only', 'HEAD'], text=True).splitlines()
    if any(not name.startswith('dist/') for name in changed):
        raise ValueError('Upstream source has uncommitted edits outside dist/')
    upstream = (source / 'dist/Savant-Card.js').read_bytes()
    text = upstream.decode('utf-8')
    if re.search(r'^(?:import|export)\s', text, flags=re.MULTILINE):
        raise ValueError('Expected a self-contained Vite bundle; review changed upstream packaging')
    if 'savant-energy-breaker-board-card' not in text:
        raise ValueError('Companion element is missing')
    # Preserve upstream UI and license comments. Only remove the unshipped source-map
    # pointer and correct the upstream picker documentation link.
    text = re.sub(r'^//# sourceMappingURL=.*\n?', '', text, flags=re.MULTILINE)
    text = text.replace('https://github.com/brett/savant-energy-breaker-board-card', REPOSITORY)
    bundle = ('/* Savant-Card upstream: ' + revision + '; see Savant-Card.LICENSE */\n'
              '(function () {\n'
              'if (customElements.get("savant-energy-breaker-board-card")) return;\n' +
              text + '\n})();\n').encode()
    compatibility = b'''/* Compatibility alias only. Savant Energy or an existing HACS resource loads the board. */
(function () {
  const legacy = "savant-energy-scenes-card";
  if (customElements.get(legacy)) return;
  customElements.whenDefined("savant-energy-breaker-board-card").then(() => {
    if (customElements.get(legacy)) return;
    const Board = customElements.get("savant-energy-breaker-board-card");
    class LegacyScenesCard extends Board {
      setConfig(config) {
        super.setConfig({
          ...config,
          type: "custom:savant-energy-breaker-board-card",
          display: {...config.display, show_title: config.show_header !== false && config.display?.show_title !== false},
        });
      }
    }
    customElements.define(legacy, LegacyScenesCard);
  });
})();
'''
    license_text = (source / 'LICENSE').read_bytes()
    package = json.loads((source / 'package.json').read_text())
    files = {'Savant-Card.js': bundle, 'savant-energy-scenes-card.js': compatibility, 'Savant-Card.LICENSE': license_text}
    metadata = {'repository': REPOSITORY, 'commit': revision, 'package_version': package['version'],
                'upstream_artifact_sha256': digest(upstream),
                'files': {name: digest(data) for name, data in files.items()},
                'adaptations': ['Guard repeated loading of the complete bundle',
                                'Correct picker documentation URL',
                                'Remove unshipped source-map pointer',
                                'Replace legacy implementation with a type alias']}
    ASSETS.mkdir(exist_ok=True)
    for name, data in files.items():
        (ASSETS / name).write_bytes(data)
    (ASSETS / 'bundle.json').write_text(json.dumps(metadata, indent=2) + '\n')
    (INTEGRATION / 'card_version.py').write_text(
        '"""Generated by tools/bundle_companion.py; do not edit."""\n'
        'CARD_VERSION = "' + digest(bundle)[:16] + '"\n')
    print('Bundled Savant-Card ' + revision)


def check():
    metadata = json.loads((ASSETS / 'bundle.json').read_text())
    if metadata['repository'] != REPOSITORY or not re.fullmatch(r'[a-f0-9]{40}', metadata['commit']):
        raise ValueError('Invalid upstream provenance')
    expected = {'Savant-Card.js', 'savant-energy-scenes-card.js', 'Savant-Card.LICENSE'}
    if set(metadata['files']) != expected:
        raise ValueError('Unexpected frontend artifact set')
    for name, expected_hash in metadata['files'].items():
        if digest((ASSETS / name).read_bytes()) != expected_hash:
            raise ValueError('Bundled file changed without sync: ' + name)
    version = digest((ASSETS / 'Savant-Card.js').read_bytes())[:16]
    if 'CARD_VERSION = "' + version + '"' not in (INTEGRATION / 'card_version.py').read_text():
        raise ValueError('Frontend cache version is stale')
    if (INTEGRATION / 'savant-energy-scenes-card.js').exists():
        raise ValueError('Old scenes-only implementation must not be shipped')
    print('Frontend provenance, file hashes, and cache version verified.')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--source', type=Path, help='Tested upstream checkout after npm ci, npm test, npm run build')
    group.add_argument('--check', action='store_true')
    args = parser.parse_args()
    if args.source:
        import_bundle(args.source.resolve())
    else:
        check()
